{
  "name": "Dra. Mirella Aesthetic",
  "description": "A luxury dental clinic website offering a new standard in dentistry with a focus on aesthetic and health."
}

import React from 'react';
import ReactDOM from 'react-dom/client';
import App from './App';

const rootElement = document.getElementById('root');
if (!rootElement) {
  throw new Error("Could not find root element to mount to");
}

const root = ReactDOM.createRoot(rootElement);
root.render(
  <React.StrictMode>
    <App />
  </React.StrictMode>
);

import React from 'react';
import Header from './components/Header';
import Hero from './components/Hero';
import IntroSection from './components/IntroSection';
import FeatureGrid from './components/FeatureGrid';
import Gallery from './components/Gallery';
import ProcessSteps from './components/ProcessSteps';
import Footer from './components/Footer';

const App: React.FC = () => {
  return (
    <div className="font-sans text-primary antialiased bg-background overflow-x-hidden">
      <Header />
      <main>
        <Hero />
        <IntroSection />
        <FeatureGrid />
        <Gallery />
        <ProcessSteps />
      </main>
      <Footer />
    </div>
  );
};

export default App;

import React, { useState, useEffect } from 'react';
import { Menu, X } from 'lucide-react';

const Header: React.FC = () => {
  const [isScrolled, setIsScrolled] = useState(false);
  const [isMobileMenuOpen, setIsMobileMenuOpen] = useState(false);

  useEffect(() => {
    const handleScroll = () => {
      setIsScrolled(window.scrollY > 50);
    };

    window.addEventListener('scroll', handleScroll);
    return () => window.removeEventListener('scroll', handleScroll);
  }, []);

  const logoUrl = "https://storage.googleapis.com/ai-studio-bucket-212404626118-us-west1/WEBS/dra_mirella/dra_mirella_logo.png";

  const navLinks = [
    { label: 'What We Do', href: '#' },
    { label: 'Who We Are', href: '#' },
    { label: 'Our Work', href: '#' },
  ];

  return (
    <header 
      className={`fixed top-0 w-full z-50 transition-all duration-300 ease-in-out ${
        isScrolled ? 'bg-background/95 backdrop-blur-sm py-4 shadow-sm' : 'bg-transparent py-6'
      }`}
    >
      <div className="max-w-[1920px] mx-auto px-6 md:px-12 flex justify-between items-center">
        {/* Logo */}
        <a href="#" className="relative z-50">
          <img 
            src={logoUrl} 
            alt="Dra. Mirella Logo" 
            className={`transition-all duration-300 ${isScrolled ? 'h-12' : 'h-16 md:h-20'}`}
          />
        </a>

        {/* Desktop Navigation */}
        <nav className="hidden lg:flex items-center space-x-12">
          {navLinks.map((link) => (
            <a 
              key={link.label}
              href={link.href} 
              className={`text-xs font-bold tracking-[0.2em] uppercase hover:text-secondary transition-colors ${
                isScrolled ? 'text-primary' : 'text-primary' // Always dark/primary as per the aesthetic logo background usually allows, or if hero is dark text needs to be light.
                // Assuming Hero allows dark text or logo is dark. Based on logo image, it looks dark.
              }`}
            >
              {link.label}
            </a>
          ))}
          <a 
            href="#" 
            className="text-xs font-bold tracking-[0.2em] uppercase border-b border-primary pb-1 hover:text-secondary hover:border-secondary transition-colors"
          >
            Schedule a Consultation
          </a>
        </nav>

        {/* Mobile Menu Button */}
        <button 
          className="lg:hidden relative z-50 p-2 text-primary"
          onClick={() => setIsMobileMenuOpen(!isMobileMenuOpen)}
        >
          {isMobileMenuOpen ? <X size={24} /> : <Menu size={24} />}
        </button>

        {/* Mobile Navigation Overlay */}
        <div 
          className={`fixed inset-0 bg-background z-40 flex flex-col justify-center items-center space-y-8 transition-transform duration-500 ease-in-out lg:hidden ${
            isMobileMenuOpen ? 'translate-x-0' : 'translate-x-full'
          }`}
        >
          {navLinks.map((link) => (
            <a 
              key={link.label}
              href={link.href} 
              className="text-lg font-bold tracking-[0.2em] uppercase text-primary hover:text-secondary"
              onClick={() => setIsMobileMenuOpen(false)}
            >
              {link.label}
            </a>
          ))}
          <a 
            href="#" 
            className="text-lg font-bold tracking-[0.2em] uppercase border-b border-primary pb-1"
            onClick={() => setIsMobileMenuOpen(false)}
          >
            Schedule a Consultation
          </a>
        </div>
      </div>
    </header>
  );
};

export default Header;

