  ];

  // Logic for text color: White at top, Dark when scrolled.
  const textColorClass = isScrolled ? 'text-primary' : 'text-white';
  const mobileButtonColor = isMobileMenuOpen ? 'text-primary' : textColorClass;

  // Button Logic:
  // Initial (Top): Bg White, Text Black.
  // Scrolled: Bg Black (Primary), Text White.
  const buttonClass = isScrolled 
    ? "bg-primary text-white hover:bg-gray-800" 
    : "bg-white text-black hover:bg-gray-100";

  const toggleLanguage = () => {
    setLanguage(language === 'es' ? 'en' : 'es');
  };

  const handleNavClick = () => {
    setIsMobileMenuOpen(false);
  };

  // Header Background Logic
  const headerBg = isMobileMenuOpen 
    ? 'bg-transparent' 
    : isScrolled 
      ? 'bg-white/95 backdrop-blur-sm shadow-sm' 
      : 'bg-transparent';

  const headerPadding = isScrolled ? 'py-4' : 'py-6';

  return (
    <header 
      className={`fixed top-0 w-full z-50 transition-all duration-300 ease-in-out ${headerBg} ${headerPadding}`}
