            alt="Officia Medical Logo" 
            className={`transition-all duration-300 ${isScrolled ? 'h-12' : 'h-16 md:h-20'}`}
          />
        </a>

        {/* Desktop Navigation - Absolute Center */}
        <nav className={`hidden lg:flex items-center space-x-12 absolute left-1/2 transform -translate-x-1/2 ${textColorClass}`}>
