            <a 
              key={link.label}
              href={link.href} 
              className="group relative text-xs font-bold tracking-[0.2em] uppercase transition-colors"
            >
              {link.label}
              {/* Underline Animation */}
              <span className="absolute left-0 -bottom-2 w-0 h-[1px] bg-current transition-all duration-300 group-hover:w-full"></span>
            </a>
          ))}
        </nav>

        {/* Desktop Right Actions (Schedule + Language) */}
        <div className={`hidden lg:flex items-center gap-6 ${textColorClass}`}>
           <button 
            onClick={toggleLanguage}
            className="text-xs font-bold tracking-[0.2em] uppercase hover:opacity-70 transition-opacity"
          >
            {language === 'es' ? 'EN' : 'ES'}
          </button>

          <a 
            href="#services" 
            className={`text-xs font-bold tracking-[0.2em] uppercase px-8 py-3 transition-colors duration-300 ${buttonClass}`}
          >
            {t.header.schedule}
          </a>
        </div>

        {/* Mobile Menu Button */}
        <button 
          className={`lg:hidden relative z-50 p-2 ${mobileButtonColor} hover:text-secondary transition-colors`}
          onClick={() => setIsMobileMenuOpen(!isMobileMenuOpen)}
        >
          {isMobileMenuOpen ? <X size={24} /> : <Menu size={24} />}
        </button>

        {/* Mobile Navigation Overlay - Sidebar Right */}
        <div 
          className={`fixed inset-0 bg-white z-40 flex flex-col justify-center items-center space-y-8 transition-transform duration-500 ease-in-out lg:hidden ${
            isMobileMenuOpen ? 'translate-x-0' : 'translate-x-full'
          }`}
        >
          {navLinks.map((link) => (
            <a 
              key={link.label}
              href={link.href} 
              className="text-lg font-bold tracking-[0.2em] uppercase text-primary hover:text-secondary"
              onClick={handleNavClick}
            >
              {link.label}
            </a>
          ))}
          <button 
            onClick={() => { toggleLanguage(); handleNavClick(); }}
            className="text-lg font-bold tracking-[0.2em] uppercase text-primary hover:text-secondary"
          >
            {language === 'es' ? 'Switch to English' : 'Cambiar a Español'}
